def transform(grid):
    H = len(grid); W = len(grid[0])
    colors = set(v for row in grid for v in row)
    B = None; sep_rows = None; sep_cols = None
    for cand in colors:
        sr = [r for r in range(H) if all(grid[r][c] != cand for c in range(W))]
        sc = [c for c in range(W) if all(grid[r][c] != cand for r in range(H))]
        if not sr or not sc:
            continue
        srs = set(sr); scs = set(sc)
        ok = True
        for r in range(H):
            if r in srs:
                continue
            for c in range(W):
                if c in scs:
                    continue
                if grid[r][c] != cand:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            B = cand; sep_rows = sr; sep_cols = sc
            break
    if B is None:
        return [row[:] for row in grid]
    from collections import Counter
    cnt = Counter()
    for r in sep_rows:
        cnt.update(grid[r])
    for c in sep_cols:
        for r in range(H):
            cnt[grid[r][c]] += 1
    cnt.pop(B, None)
    bg = cnt.most_common(1)[0][0] if cnt else 0
    def row_has_marker(r):
        return any(grid[r][c] != bg for c in range(W))
    def col_has_marker(c):
        return any(grid[r][c] != bg for r in range(H))
    brs = [(sep_rows[i], sep_rows[i+1]) for i in range(len(sep_rows)-1)
           if row_has_marker(sep_rows[i]) and row_has_marker(sep_rows[i+1])]
    bcs = [(sep_cols[j], sep_cols[j+1]) for j in range(len(sep_cols)-1)
           if col_has_marker(sep_cols[j]) and col_has_marker(sep_cols[j+1])]
    out = []
    for (r1, r2) in brs:
        row = []
        for (c1, c2) in bcs:
            a = grid[r1][c1]; b = grid[r1][c2]
            d = grid[r2][c1]; e = grid[r2][c2]
            if a == b == d == e and a != bg:
                row.append(a)
            else:
                row.append(B)
        out.append(row)
    return out
